// Кейс: .qa/tests/monitoring/MON-012.md · план: .qa/e2e-app/specs/app.md (1.8)
// «בדיקת בטיחות», строка «עוצמת צפצוף מקסימלית» при громкости на максимуме: тестовый звук → «שמעתי» → «5 מתוך 5», «המשך» активна.
// РУЧНОЕ ПРЕДУСЛОВИЕ: громкость iPhone на максимуме (кнопками сбоку) — Appium громкость не выставляет.
// Тестовый сигнал звучит громко. Мониторинг НЕ запускается («המשך» не нажимается).
import { by, assert, skip } from '../../lib/appium.mjs';
import { openSafetyCheck, waitEnabled } from '../../lib/banci.mjs';

export const name = 'בדיקת בטיחות: громкость на максимуме → «השמיעו את צליל הבדיקה…» → лист «בדיקת צליל ההתרעה» → «שמעתי» → «5 מתוך 5», «המשך» активна #e2f5c7 @iphone @app @prod-safe';

export default async function (app) {
  await openSafetyCheck(app);
  await app.waitFor(by.contains('עוצמת צפצוף מקסימלית'), { timeout: 20000, what: 'строка «עוצמת צפצוף מקסימלית»' });

  // Ручное предусловие: громкость не на максимуме — тест пропускается, а не падает.
  if (await app.exists(by.contains('עוצמת הקול כבויה')) || await app.exists(by.contains('עוצמת הקול נמוכה'))) {
    skip('громкость iPhone не на максимуме (строка «עוצמת הקול כבויה/נמוכה…») — поднять громкость до конца кнопками сбоку и перезапустить тест');
  }

  // 1. Строка-подсказка при максимальной громкости.
  const row = await app.waitFor(by.contains('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו'), { timeout: 15000, what: 'строка «השמיעו את צליל הבדיקה ואשרו ששמעתם אותו.»' });

  // 2. Тап → лист «בדיקת צליל ההתרעה» с «השמעה» и «שמעתי».
  await row.click();
  await app.waitFor(by.contains('בדיקת צליל ההתרעה'), { timeout: 10000, what: 'лист «בדיקת צליל ההתרעה»' });
  await app.waitFor(by.exact('השמעה'), { what: 'кнопка «השמעה» в листе' });
  await app.waitFor(by.exact('שמעתי'), { what: 'кнопка «שמעתי» в листе' });

  // 3. «השמעה» (звук) → «שמעתי» → лист закрыт.
  await app.tap(by.exact('השמעה'));
  await app.tap(by.exact('שמעתי'), { what: '«שמעתי»' });
  await app.waitGone(by.contains('בדיקת צליל ההתרעה'), { what: 'лист «בדיקת צליל ההתרעה» закрылся' });

  // 4. Все проверки пройдены: «5 מתוך 5», «המשך» активна.
  await app.waitFor(by.contains('5 מתוך 5'), {
    timeout: 15000,
    what: '«5 מתוך 5» (если другое число — ПРЕДУСЛОВИЕ: другая строка с ⚠ — батарея > 30% или зарядка, уведомления/камера разрешены, второй телефон подключён)',
  });
  assert(!(await app.exists(by.contains('עוצמת הקול כבויה'))) && !(await app.exists(by.contains('עוצמת הקול נמוכה'))), 'после «שמעתי» нет предупреждения о громкости');
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך»' });
  await waitEnabled(next, true, { what: '«המשך» после «שמעתי» (5 מתוך 5)' });

  // Выход без запуска мониторинга.
  await app.restart();
}
